# ---------------------------------------------------------------- THE ONE DOOR

def rankable(cells):
    """⭐ THE ONLY ENTRY POINT to every interval, bootstrap and ranking.

    A cell is admitted SOLELY on `mcd_value is not None`, and that field is set
    to a number ONLY inside `measure_cell()` when the support domain passed.
    There is no other code path into a ranking, and no way to pass a cell in
    that failed the domain.
    """
    return [c for c in cells if c.get("mcd_value") is not None]


def excluded(cells):
    """The exact complement of `rankable()`, for the ledger.

    ⭐ SPEC S11.3. This exists so that REPORTING how many cells were excluded
    never requires a second piece of code to read `mcd_value` and decide. The
    proof parses this module and fails if any function other than `rankable()`
    uses `mcd_value` in a decision; counting exclusions in `aggregate()` used to
    trip exactly that, and the fix is one door, not an exemption.
    """
    keep = {id(c) for c in rankable(cells)}
    return [c for c in cells if id(c) not in keep]


def measure_cell(src16, est16, state, arm):
    """One cell. SUPPORT FIRST, then alignment, then mcd. Order is structural."""
    out = {"support_state": None, "mcd_value": None, "mcd_state": None}

    # (c) THE DOMAIN. Evaluated BEFORE anything numeric exists.
    sup = SUP.validated_support(src16, est16, RANK_SR)
    out["support_state"] = sup["state"]
    out["supported_up_to_hz"] = sup.get("supported_up_to_hz")
    if not sup["in_support"]:
        out["mcd_state"] = NOT_SUPPORTED       # a STATE, never a number
        return out

    al = G4.alignment(src16, est16, RANK_SR)
    out["alignment_state"] = al["state"]
    out["envelope_correlation"] = al.get("envelope_correlation")
    out["delay_samples"] = al.get("delay_samples")
    if al["state"] != "MEASURED":
        out["mcd_state"] = NOT_ESTABLISHED
        return out

    m = G4.mcd(src16, est16, RANK_SR, delay_samples=al["delay_samples"],
               length_tol=max(len(src16), len(est16)))
    if m.get("value") is None:
        out["mcd_state"] = m.get("state", "UNKNOWN")
        return out
    out["mcd_value"] = float(m["value"])       # the ONLY place this is set
    out["mcd_state"] = "MEASURED"
    return out


# ---------------------------------------------------------------- per-arm pass

_SRC = {}


def source16(path, rung):
    key = (path, rung)
    if key in _SRC:
        return _SRC[key]
    x, sr = sf.read(path, dtype="float64", always_2d=True)
    x = x.mean(axis=1)
    if rung:
        x = x[:int(round(rung * sr))]
    y, _ = G4.resample(x, sr, RANK_SR)
    y = y.astype(np.float32)
    if len(_SRC) < 2200:
        _SRC[key] = y
    return y


def run_arm(arm, rows, g2, corpus_paths):
    out = os.path.join(OUT_DIR, "gate4_stage2_%s.jsonl" % arm)
    done = set()
    if os.path.isfile(out):
        for l in open(out):
            try:
                done.add(json.loads(l)["key"])
            except Exception:
                pass
    cells = [r for r in rows if r.get("arm") == arm and r.get("status") == "OK"]
    t0, n = time.time(), 0
    with open(out, "a") as f:
        for r in cells:
            if r["key"] in done:
                continue
            row = {k: r[k] for k in ("key", "arm", "set", "speaker", "sex",
                                     "state", "index", "rung_s", "source_file")}
            row["route"] = g2[arm]["route"]
            try:
                sp = corpus_paths[(r["speaker"], r["state"], r["index"])]
                s16 = source16(sp, r["rung_s"])

                # OFFLINE: §8 first. An inadmissible signal gets NO metric.
                if r.get("offline_gate8") != "PASS":
                    row["offline"] = {"mcd_state": INADMISSIBLE,
                                      "mcd_value": None,
                                      "gate8": r.get("offline_gate8"),
                                      "failing": r.get("offline_gate8_failing")}
                else:
                    o, osr = sf.read(r["offline_path"], dtype="float64",
                                     always_2d=True)
                    o16, _ = G4.resample(o.mean(axis=1), osr, RANK_SR)
                    row["offline"] = measure_cell(s16, o16, r["state"], arm)
                    row["offline"]["gate8"] = "PASS"

                # STREAMED, and Q1 = the within-arm streaming cost (tier A).
                if r.get("streamed_path") and os.path.isfile(r["streamed_path"]):
                    if r.get("streamed_gate8") != "PASS":
                        row["streamed"] = {"mcd_state": INADMISSIBLE,
                                           "mcd_value": None,
                                           "gate8": r.get("streamed_gate8")}
                    else:
                        st, ssr = sf.read(r["streamed_path"], dtype="float64",
                                          always_2d=True)
                        s2, _ = G4.resample(st.mean(axis=1), ssr, RANK_SR)
                        row["streamed"] = measure_cell(s16, s2, r["state"], arm)
                        row["streamed"]["gate8"] = "PASS"
                        if r.get("offline_gate8") == "PASS":
                            # Q1: streamed vs THIS ARM'S OWN full-context decode.
                            # Tier A, aligned by construction. DETECTOR only.
                            n_ = min(len(o16), len(s2))
                            d = G4.max_abs_err(o16[:n_], s2[:n_],
                                               length_tol=abs(len(o16) - len(s2)) + 1)
                            row["Q1_streaming_cost"] = {
                                "max_abs_err": d.get("value"),
                                "rel_pct": d.get("rel_pct"),
                                "label": "DETECTOR - within-arm only; NOT a "
                                         "quality ranking between decoders"}
                else:
                    row["streamed"] = {"mcd_state": "NO STREAMED OUTPUT",
                                       "mcd_value": None,
                                       "reason": r.get("streamed_state")}
                row["status"] = "OK"
            except Exception as e:
                row["status"] = "FAILED"
                row["error"] = "%s: %s" % (type(e).__name__, e)
            f.write(json.dumps(row) + "\n")
            n += 1
            if n % 250 == 0:
                f.flush()
                print("    %s %d/%d  %.0fs" % (arm, n, len(cells), time.time() - t0),
                      flush=True)
    print("  %-28s %5d cells  %.0fs" % (arm, n, time.time() - t0), flush=True)


