#: ⭐ SPEC S1 / S2. THE EXPERIMENTAL UNIT AND ITS STRATUM, DEFINED ONCE.
#: `k` is a cell key (speaker, state, index, rung_s).
#:
#: MAJOR-1. The shipped code used (speaker, index, rung_s), wrong in both halves:
#: it OMITTED `state`, merging performances GATE4_PREREG.md 11.2.1 defines as
#: different recordings - 11.2.1 DEFINES the unit as one performance by one
#: speaker in ONE STATE, which is the whole justification; a descriptive corpus
#: count once quoted here was unpersisted and is WITHDRAWN - and it INCLUDED
#: `rung_s`, splitting 56 ladder recordings five ways each - the precise defect
#: 11.2.2 names ("contributes all five or none").
#:
#: The stratum is DERIVED from the key, never stored separately: the shipped
#: `grp_of[rk] = gk` was last-write-wins, so a merged cluster's state label was
#: an artifact of sort order.
def REC(k):
    """SPEC S1: recording = (speaker, state, index). Rungs travel together."""
    return (k[0], k[1], k[2])


def GRP(k):
    """SPEC S2: group = (speaker, state), derived from the recording key."""
    return (k[0], k[1])


#: ⭐ SPEC S7.1. THE CLASSIFICATION CONSTANTS, DECLARED AND FROZEN.
#: ⚠️ SPEC section 0: chosen by an author who had seen the data. Freezing makes
#: them declared and auditable, NOT blind. Both sit inside an EMPTY GAP in the
#: observed distribution (17..714 paired cells; 1.0%..31.3% coverage), so no
#: value in either gap produces a different partition - a measured property, not
#: a claim of blindness.
WELL_POWERED_MIN_PAIRED = 100
LOW_COVERAGE_PCT = 5.0
FLOOR_UNCERTAINTY_QUANTILES = (2.5, 97.5)
FLOOR_BOOT_RESAMPLES = 4000
FLOOR_BOOT_SEED = 20260911


def floor_uncertainty():
    """SPEC S7.2. The instrument floor's OWN 95% interval, from the 16 frozen
    draws GATE4_PREREG.md 6.1.4 limitation 5 already declares.

    ⛔ NEVER changes a verdict (S7.2). It classifies evidence strength only.
    """
    d = json.load(open(os.path.join(HERE, "fuzz_gate4_lib.json"),
                       encoding="utf-8"))["INSTRUMENT_FLOORS"]["mcd"]["per_state"]
    out = {}
    for st, rec in d.items():
        v = np.array([x["value"] for x in rec["draws"]], dtype=float)
        q = float(rec["quantile"])
        rng = np.random.default_rng(FLOOR_BOOT_SEED)
        b = [float(np.quantile(rng.choice(v, size=v.size, replace=True), q))
             for _ in range(FLOOR_BOOT_RESAMPLES)]
        lo, hi = np.percentile(b, list(FLOOR_UNCERTAINTY_QUANTILES))
        out[st] = {"floor": float(rec["floor_absolute"]),
                   "floor_lo": float(lo), "floor_hi": float(hi),
                   "max_draw": float(v.max()), "min_draw": float(v.min()),
                   "n_draws": int(rec["n_draws"]), "quantile": q,
                   # ⛔ audit-3 M1: floor_hi is pinned at max(draws) by
                   # construction - a 0.95 quantile of a resample cannot exceed
                   # the sample maximum. Recorded on every state.
                   "floor_hi_is_max_draw": bool(abs(hi - v.max()) < 1e-9)}
    return out


def _hier_point(take, by_rec, grp_of, rec_val=None):
    """§11.2.3 AGGREGATION HIERARCHY: cell -> recording -> (speaker x state)
    -> arm, so a speaker with more admissible recordings cannot dominate.

    M2. The previous code took a FLAT median over every cell, which is the
    `cell -> arm` path the pre-registration does not declare. Recorded as a
    deviation, not silently replaced.

    `rec_val` is the cell->recording reduction (S1.2), precomputed once because
    it cannot change between resamples. Pure performance; identical result.
    """
    groups = {}
    for r in take:
        v = rec_val[r] if rec_val is not None else float(np.median(by_rec[r]))
        groups.setdefault(grp_of[r], []).append(v)
    if not groups:
        return None
    return float(np.median([float(np.median(v)) for v in groups.values()]))


def _flat_point(take, by_rec):
    """The DEVIATION that was actually measured before M2: a flat median over
    every cell, ignoring the hierarchy. Kept only so the record shows it."""
    vals = [v for r in take for v in by_rec[r]]
    return float(np.median(vals)) if vals else None


def cluster_bootstrap(items, n=N_RESAMPLES, seed=SEED):
    """§11.2.2: resample RECORDINGS with replacement, 4000 draws, seed 20260911,
    95% percentile, point estimate the median. One recording is one draw and
    every cell belonging to it travels with it. Paired estimands draw the
    recording ONCE and take both arms from that draw.

    `items` are `(recording_key, group_key, value)`, where `group_key` is the
    (speaker x state) cell §11.2.3 aggregates within first.

    ⛔ M1. THERE IS NO MINIMUM-RECORDING REFUSAL HERE. The previous code
    returned None below 3 recordings, and the caller then labelled the pair
    `ORDERED, SEPARATION NOT ESTABLISHED` - a first-class state §11.1 defines as
    displaying its interval - with NO interval in existence. That threshold was
    undisclosed and is gone. The procedure is defined for any n >= 1; where it
    is degenerate the result SAYS SO and the caller fails the pair closed.
    """
    by_rec, grp_of = {}, {}
    for rk, gk, v in items:
        by_rec.setdefault(rk, []).append(v)
        grp_of[rk] = gk
    keys = sorted(by_rec)
    if not keys:
        return None
    # S1.2, computed ONCE: a recording contributes the median of its own cells.
    rec_val = {k: float(np.median(by_rec[k])) for k in keys}
    rng = np.random.default_rng(seed)
    idx = np.arange(len(keys))
    meds = []
    draws = rng.choice(idx, size=(n, len(keys)), replace=True)
    for row in draws:
        take = [keys[t] for t in row]
        meds.append(_hier_point(take, by_rec, grp_of, rec_val))
    lo, hi = np.percentile(meds, [(100 - CI) / 2, 100 - (100 - CI) / 2])
    ngroups = len({grp_of[k] for k in keys})
    return {
        "median": _hier_point(keys, by_rec, grp_of, rec_val),
        "ci_lo": float(lo), "ci_hi": float(hi),
        "n_recordings": len(keys), "n_cells": sum(len(v) for v in by_rec.values()),
        "n_speaker_state_groups": ngroups,
        "n_resamples": n, "seed": seed, "ci_pct": CI,
        "aggregation": "cell -> recording -> (speaker x state) -> arm (11.2.3)",
        # ⚠️ M2, RECORDED: what the flat-median path the audit found would give.
        "deviation_flat_median_cells": _flat_point(keys, by_rec),
        # ⚠️ M1, RECORDED: an interval this thin is not an interval.
        "degenerate": bool(len(keys) < 3 or ngroups < 2),
        "degenerate_reason": (
            None if (len(keys) >= 3 and ngroups >= 2) else
            "fewer than 3 recordings" if len(keys) < 3 else
            "all recordings fall in ONE (speaker x state) group, so the "
            "hierarchy has nothing to aggregate across"),
    }


