def determinism():
    """{arm: verdict} from every gate4_determinism_<env>.jsonl on disk."""
    out = {}
    for f in glob.glob(os.path.join(OUT_DIR, "gate4_determinism_*.jsonl")):
        for l in open(f):
            try:
                r = json.loads(l)
            except Exception:
                continue
            if r.get("arm"):
                out[r["arm"]] = r.get("verdict")
    return out


def retro_sha():
    """M3: the retrospective Stage 1 reproduction check, per arm."""
    out = {}
    for f in glob.glob(os.path.join(OUT_DIR, "gate4_retro_sha_*.jsonl")):
        for l in open(f):
            try:
                r = json.loads(l)
            except Exception:
                continue
            if r.get("arm"):
                out[r["arm"]] = {k: r.get(k) for k in
                                 ("verdict", "n_probes", "n_match",
                                  "n_file_unchanged", "n_samples_bit_identical",
                                  "sample_seed", "warmup_cell")}
    return out


